import React from "react";

export default function Navbar({ active }) {
  const tabs = [
    { id: "progress", label: "📊 Progress" },
    { id: "jap", label: "🧘 Jap" },
    { id: "mind", label: "🧠 Mind" },
    { id: "routine", label: "⏰ Routine" },
    { id: "satsang", label: "🙏 Satsang" }
  ];

  return (
    <div style={{
      display: "flex",
      justifyContent: "space-around",
      marginBottom: "20px",
      flexWrap: "wrap",
      gap: "8px"
    }}>
      {tabs.map(tab => (
        <button
          key={tab.id}
          onClick={() => setActive(tab.id)}
          style={{
            padding: "8px 14px",
            borderRadius: "8px",
            border: "none",
            cursor: "pointer",
            background: active === tab.id ? "#4CAF50" : "#ddd",
            color: active === tab.id ? "white" : "black"
          }}
        >
          {tab.label}
        </button>
      ))}
    </div>
  );
}
